BEGIN;
INSERT INTO public.site_pages(page_key,content,content_en,is_published,updated_at)
VALUES ('whatsapp-templates','{"payment_request":"مرحباً {{customerName}}،\nنشكركم لطلبكم من الشيف مجاهد.\nتمت مراجعة طلبكم رقم: {{reference}}.\nالمبلغ المطلوب لإتمام الطلب: {{totalJod}} JOD.\n\nطريقة الدفع: {{paymentInstructions}}\n\nبعد إتمام الدفع، يرجى إرسال صورة الإيصال أو تأكيد التحويل في هذه المحادثة. سنعتمد الطلب ونبدأ التجهيز فور التحقق.\nمع الشكر، فريق الشيف مجاهد.","customer_chat":"مرحباً، بخصوص طلبكم رقم {{reference}}","status_approved":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nتم تأكيد واعتماد طلبكم، وسيتم تحضيره وفق التفاصيل المتفق عليها.\n\nفريق الشيف مجاهد","status_preparing":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nبدأ فريق الشيف مجاهد تحضير طلبكم.\n\nفريق الشيف مجاهد","status_ready_collection":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nطلبكم جاهز للاستلام من الشيف مجاهد.\n\nفريق الشيف مجاهد","status_ready_delivery":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nطلبكم جاهز، ونعمل على ترتيبات توصيله.\n\nفريق الشيف مجاهد","status_out_for_delivery":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nطلبكم الآن في طريقه للتوصيل.\n\nفريق الشيف مجاهد","status_completed_collection":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nتم تسجيل استلام طلبكم. شكراً لثقتكم بنا.\n\nفريق الشيف مجاهد","status_completed_delivery":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nتم تسجيل تسليم طلبكم. شكراً لثقتكم بنا.\n\nفريق الشيف مجاهد","handoff_b2c":"مرحباً، أود متابعة الطلب المسجل لدى الشيف مجاهد.\nرقم المرجع: {{reference}}","handoff_b2b":"مرحباً، أود متابعة طلب الشركات المسجل لدى الشيف مجاهد.\nرقم المرجع: {{reference}}"}'::jsonb,'{"payment_request":"مرحباً {{customerName}}،\nنشكركم لطلبكم من الشيف مجاهد.\nتمت مراجعة طلبكم رقم: {{reference}}.\nالمبلغ المطلوب لإتمام الطلب: {{totalJod}} JOD.\n\nطريقة الدفع: {{paymentInstructions}}\n\nبعد إتمام الدفع، يرجى إرسال صورة الإيصال أو تأكيد التحويل في هذه المحادثة. سنعتمد الطلب ونبدأ التجهيز فور التحقق.\nمع الشكر، فريق الشيف مجاهد.","customer_chat":"مرحباً، بخصوص طلبكم رقم {{reference}}","status_approved":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nتم تأكيد واعتماد طلبكم، وسيتم تحضيره وفق التفاصيل المتفق عليها.\n\nفريق الشيف مجاهد","status_preparing":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nبدأ فريق الشيف مجاهد تحضير طلبكم.\n\nفريق الشيف مجاهد","status_ready_collection":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nطلبكم جاهز للاستلام من الشيف مجاهد.\n\nفريق الشيف مجاهد","status_ready_delivery":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nطلبكم جاهز، ونعمل على ترتيبات توصيله.\n\nفريق الشيف مجاهد","status_out_for_delivery":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nطلبكم الآن في طريقه للتوصيل.\n\nفريق الشيف مجاهد","status_completed_collection":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nتم تسجيل استلام طلبكم. شكراً لثقتكم بنا.\n\nفريق الشيف مجاهد","status_completed_delivery":"مرحباً {{customerName}}،\nتحديث بخصوص طلبكم من الشيف مجاهد رقم {{reference}}:\nتم تسجيل تسليم طلبكم. شكراً لثقتكم بنا.\n\nفريق الشيف مجاهد","handoff_b2c":"مرحباً، أود متابعة الطلب المسجل لدى الشيف مجاهد.\nرقم المرجع: {{reference}}","handoff_b2b":"مرحباً، أود متابعة طلب الشركات المسجل لدى الشيف مجاهد.\nرقم المرجع: {{reference}}"}'::jsonb,true,now())
ON CONFLICT (page_key) DO NOTHING;

-- Preserve the existing approved CliQ account number and add the bank description.
-- Do not overwrite any later manual change.
UPDATE public.site_pages
SET content=jsonb_set(content,'{paymentInstructions}',to_jsonb('كليك (بنك الاتحاد)'||E'\n'||'0798265415'::text),true),
    updated_at=now()
WHERE page_key='contact'
